	private static byte[] tar(Map<String, byte[]> entries) throws IOException {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		try (TarArchiveOutputStream tar = new TarArchiveOutputStream(output)) {
			for (Map.Entry<String, byte[]> value : entries.entrySet()) {
				TarArchiveEntry entry = new TarArchiveEntry(value.getKey());
				entry.setSize(value.getValue().length);
				tar.putArchiveEntry(entry);
				tar.write(value.getValue());
				tar.closeArchiveEntry();
			}
		}
		return output.toByteArray();
	}

	private static byte[] v7Tar(Map<String, byte[]> entries) throws IOException {
		byte[] archive = tar(entries);
		Arrays.fill(archive, 257, 263, (byte) 0);
		Arrays.fill(archive, 148, 156, (byte) ' ');
		long checksum = 0;
		for (int i = 0; i < 512; i++) {
			checksum += archive[i] & 0xff;
		}
		byte[] checksumField = String.format(Locale.ROOT, "%06o\0 ", checksum)
				.getBytes(StandardCharsets.US_ASCII);
		System.arraycopy(checksumField, 0, archive, 148, checksumField.length);
		return archive;
	}

	private static byte[] tarWithNonRegularEntries() throws IOException {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		try (TarArchiveOutputStream tar = new TarArchiveOutputStream(output)) {
			TarArchiveEntry directory = new TarArchiveEntry("directory/");
			tar.putArchiveEntry(directory);
			tar.closeArchiveEntry();
			TarArchiveEntry link = new TarArchiveEntry("link.ttl", TarConstants.LF_SYMLINK);
			link.setLinkName("data.ttl");
			tar.putArchiveEntry(link);
			tar.closeArchiveEntry();
			TarArchiveEntry data = new TarArchiveEntry("data.ttl");
			data.setSize(TURTLE.length);
			tar.putArchiveEntry(data);
			tar.write(TURTLE);
			tar.closeArchiveEntry();
		}
		return output.toByteArray();
	}

	private static byte[] zip(Map<String, byte[]> entries) throws IOException {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		try (ZipOutputStream zip = new ZipOutputStream(output)) {
			for (Map.Entry<String, byte[]> value : entries.entrySet()) {
				zip.putNextEntry(new ZipEntry(value.getKey()));
				zip.write(value.getValue());
				zip.closeEntry();
			}
		}
		return output.toByteArray();
	}

	private static byte[] gzip(byte[] input) throws IOException {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		try (GZIPOutputStream gzip = new GZIPOutputStream(output)) {
			gzip.write(input);
		}
		return output.toByteArray();
	}

