	private static byte[] concat(byte[] first, byte[] second) {
		byte[] result = new byte[first.length + second.length];
		System.arraycopy(first, 0, result, 0, first.length);
		System.arraycopy(second, 0, result, first.length, second.length);
		return result;
	}

	private static final class CloseTrackingInputStream extends ByteArrayInputStream {
		private boolean closed;

		private CloseTrackingInputStream(byte[] data) {
			super(data);
		}

		@Override
		public void close() {
			closed = true;
		}
	}

	private static RDFParserFactory factory(RDFFormat format) {
		return new RDFParserFactory() {
			@Override
			public RDFFormat getRDFFormat() {
				return format;
			}

			@Override
			public RDFParser getParser() {
				throw new UnsupportedOperationException();
			}
		};
	}

	private record Terminal(String name, RDFFormat format, byte[] body) {
		@Override
		public boolean equals(Object other) {
			return other instanceof Terminal terminal
					&& name.equals(terminal.name)
					&& format.equals(terminal.format)
					&& java.util.Arrays.equals(body, terminal.body);
		}

		@Override
		public int hashCode() {
			return 31 * (31 * name.hashCode() + format.hashCode()) + java.util.Arrays.hashCode(body);
		}
	}
